47: export function digestSecret(secret) {
48:   if (typeof secret !== "string" || secret.length === 0) {
49:     throw new Error("expected a non-empty token string");
50:   }
51:   return crypto
52:     .createHash("sha256")
53:     .update(secret + readPepper())
