108:     if (row.familyClosedAt) return { err: { code: "FAMILY_CLOSED" } };
109: 
110:     if (row.retiredAt) {
111:       trx.updateByFamily(row.familyId, { familyClosedAt: now });
112:       return { err: { code: "REPLAY_DETECTED" } };
113:     }
114: 
115:     if (
116:       typeof claimedOwner === "number" &&
117:       claimedOwner > 0 &&
118:       row.ownerId !== claimedOwner
