139:       digest: nextDigest,
140:       familyId: row.familyId,
141:       ownerId: row.ownerId,
142:       expiry: nextExpiry,
143:     });
144:     trx.updateByDigest(digest, {
145:       retiredAt: now,
146:       successorDigest: nextDigest,
147:     });
