1: // An in-memory table standing in for a database. It models only the two
2: // things the token module relies on: transactions, and a lock on a single row.
3: //
4: // The module's correctness depends on the order in which writes become
5: // visible, not on any storage engine, so a real database would add setup and
6: // nothing else. `lockByDigest` plays the part of a row lock taken inside a
7: // transaction: when two transactions ask for the same row, the second waits
8: // and then sees what the first wrote.
9: 
10: class Lock {
11:   #held = false;
12:   #waiters = [];
13: 
14:   async acquire() {
15:     if (!this.#held) {
16:       this.#held = true;
17:       return;
18:     }
19:     await new Promise((resolve) => this.#waiters.push(resolve));
20:   }
21: 
22:   release() {
23:     const next = this.#waiters.shift();
24:     if (next) next();
25:     else this.#held = false;
26:   }
27: }
28: 
29: export class TokenStore {
30:   #rows = [];
31:   #locks = new Map();
32:   #txLock = new Lock();
33: 
34:   /** Snapshot of all rows for tests; copies, so the table cannot be edited through it. */
35:   all() {
36:     return this.#rows.map((r) => ({ ...r }));
37:   }
38: 
39:   insert(row) {
40:     this.#rows.push({
41:       digest: row.digest,
42:       familyId: row.familyId,
43:       ownerId: row.ownerId,
44:       expiry: row.expiry,
45:       retiredAt: row.retiredAt ?? null,
46:       familyClosedAt: row.familyClosedAt ?? null,
47:       successorDigest: row.successorDigest ?? null,
48:     });
49:   }
50: 
51:   findByDigest(digest) {
52:     const row = this.#rows.find((r) => r.digest === digest);
53:     return row ? { ...row } : null;
54:   }
55: 
56:   updateByDigest(digest, patch) {
57:     let n = 0;
58:     for (const r of this.#rows) {
59:       if (r.digest === digest) {
60:         Object.assign(r, patch);
61:         n += 1;
62:       }
63:     }
64:     return n;
65:   }
66: 
67:   updateByFamily(familyId, patch) {
68:     let n = 0;
69:     for (const r of this.#rows) {
70:       if (r.familyId === familyId) {
71:         Object.assign(r, patch);
72:         n += 1;
73:       }
74:     }
75:     return n;
76:   }
77: 
78:   /**
79:    * Calls `fn` with a handle for one transaction. The handle offers the
80:    * store's read and write methods, plus `lockByDigest`, which waits until no
81:    * other transaction holds the lock on that row.
82:    */
83:   async transaction(fn) {
84:     await this.#txLock.acquire();
85:     const held = [];
86:     try {
87:       const handle = {
88:         lockByDigest: async (digest) => {
89:           let lock = this.#locks.get(digest);
90:           if (!lock) {
91:             lock = new Lock();
92:             this.#locks.set(digest, lock);
93:           }
94:           // Give up the store-wide lock while queued for the row, so another
95:           // transaction can run meanwhile. Without this the wait could never
96:           // overlap with other work, and a missing row lock would go unseen.
97:           this.#txLock.release();
98:           await lock.acquire();
99:           held.push(lock);
100:           await this.#txLock.acquire();
101:           return this.findByDigest(digest);
102:         },
103:         insert: (row) => this.insert(row),
104:         findByDigest: (h) => this.findByDigest(h),
105:         updateByDigest: (h, patch) => this.updateByDigest(h, patch),
106:         updateByFamily: (s, patch) => this.updateByFamily(s, patch),
107:       };
108:       return await fn(handle);
109:     } finally {
110:       for (const lock of held) lock.release();
111:       this.#txLock.release();
112:     }
113:   }
114: }

