    assert.equal(retired.successorDigest, digestSecret(result.data.secret));
  });

  it("multiple rotations maintain a chain", async () => {
    let current = (await openFamily(store, 1)).secret;

    const results = [];
    for (let i = 0; i < 5; i++) {
      results.push(await exchange(store, current));
      assert.ok(results[i].data);
      current = results[i].data.secret;
    }

    // All should share the same familyId
    const familyId = results[0].data.familyId;
    for (const r of results) {
      assert.equal(r.data.familyId, familyId);
    }

    // Retired rows should point to their successors
    for (let i = 0; i < results.length - 1; i++) {
      const retiredDigest = digestSecret(results[i].data.secret);
      const retiredRow = store.findByDigest(retiredDigest);
      assert.equal(retiredRow.successorDigest, digestSecret(results[i + 1].data.secret));
    }

    // Last one should not be retired (it's the current valid token)
    const lastDigest = digestSecret(results[results.length - 1].data.secret);
    const lastRow = store.findByDigest(lastDigest);
    assert.equal(lastRow.retiredAt, null);
