    assert.equal(replay.err.code, "REPLAY_DETECTED");

    // Both the original and second token should have familyClosedAt
    const firstRow = store.findByDigest(digestSecret(current));
    assert.ok(firstRow.familyClosedAt);

    const secondRow = store.findByDigest(digestSecret(second));
    assert.ok(secondRow.familyClosedAt);

    // The successor of the second token should also be closed
    const succRow = store.findByDigest(firstRow.successorDigest); // first's successor is second
    assert.ok(succRow.familyClosedAt);
  });
});

